const e={meta:{title:"POP · SaaS pro tvůrce v UEFN"},nav:{features:"Funkce",pricing:"Ceník",faq:"Otázky",login:"Přihlásit se",join:"Do bety",home:"POP, domů",lang:"Jazyk",search:"Hledat zemi"},menu:{groups:["Organizace","Propojení s UEFN","Růst mapy"],items:[{t:"Úkoly a plánování",d:"Hodinové úkoly, milníky, sledované zpoždění."},{t:"Stránky",d:"Dokumenty, pravidla a databáze mapy."},{t:"Tabule",d:"Lístečky, tvary a šipky, společně naživo."},{t:"Tým a role",d:"Pozvěte, přidělte roli, každý ví, co dělat."},{t:"Organizér",d:"Aktéři úrovně uklizení a upravovaní hromadně."},{t:"UEFN Link",d:"Vaše projekty UEFN synchronizované s POP."},{t:"Připojené AI",d:"Claude, Cursor nebo Codex plní vaše úkoly."},{t:"POP Forge",d:"Desktopová aplikace, která staví v UEFN."},{t:"Analýza trhu",d:"Žánry, které přitahují, a ty nasycené."},{t:"Video trendy",d:"Co frčí na TikToku a YouTube Shorts."},{t:"Playtesty a vydání",d:"Nechte mapu otestovat a připravte vydání."},{t:"Výplaty",d:"Dělení výdělků a výpis pro každého."}],bottom:["Propojený Discord a GitHub","Na Macu i PC"],all:"Všechny funkce"},hero:{announce:"Uzavřená beta otevřená tvůrcům v UEFN",h1a:"Tvořte v UEFN.",h1b:"Sami nebo v týmu, bez chaosu.",subA:"POP je SaaS, který pomáhá tvůrcům v UEFN od nápadu po vydání: ",subB:"hodinové úkoly",subC:", tabule, připojené AI, analýza trhu a dělení výdělků.",cta:"Zapsat se na čekací listinu",see:"Zobrazit funkce",micro1:"Uzavřená beta",micro2:"Přístup přes čekací listinu",micro3:"Propojeno s UEFN"},marquee:{label:"Funguje s vašimi nástroji",epic:"Fortnite API od Epicu"},pain:{eyebrow:"Problém",h2a:"Discord, Google Docs, soubory všude…",h2b:"a mapa se nehýbe.",without:"Bez POP",with:"S POP",bad:["„Kdo sahal na spawner?“","Nápady se ztrácejí na Discordu","Seznam úkolů v Google Docu","Tabulka výdělků, verze 7","„Tak kdy to vlastně vydáme?“","Stavíme, aniž víme, jestli žánr funguje"],good:["Každá akce je zaznamenaná a vratná","Nápady z tabule se mění v úkoly","Hodinové úkoly se závislostmi","Přehledný výpis pro každého","Milníky a zpoždění se sledují automaticky","Verdikt pro každý žánr podle skutečných čísel"]},feat:{eyebrow:"Funkce",h2:"Vše pro tvorbu v UEFN, od nápadu po den vydání.",p:"To, co tu vidíte, jsou skutečné obrazovky POP, jen zjednodušené.",items:[{tag:"Úkoly a plánování",h:"Hodinové úkoly. Plán, který platí.",p:"Generátor rozdělí mapu na hodinové úkoly i se závislostmi. Plán sleduje milníky a upozorní na zpoždění a vestavěný asistent shrne den.",pts:["Kanban a závislosti","Sledování milníků a zpoždění","Shrnutí dne"]},{tag:"Organizér",h:"Všechna zařízení. Uklizená za tři vteřiny.",p:"Hledejte podle tagu, typu nebo složky, vyberte dvacet a přejmenujte, přesuňte nebo duplikujte najednou. Ctrl+Z vrací. Když je UEFN zavřený, změny počkají.",pts:["Hledání tag:, type:, složka:","Hromadné úpravy","Vše jde vrátit"]},{tag:"Tabule",h:"Kreslete mapu společně.",p:"Lístečky, tvary, šipky, barvy, tučné písmo, podtržení: vše pro rozvržení nápadů. Hlasujte a z nejlepších lístečků udělejte úkoly.",pts:["Kompletní formátování","Spolupráce v reálném čase","Lístečky → úkoly"]},{tag:"Analýza",h:"Vězte, co stavět, dřív než začnete.",p:"Které žánry přitahují hráče, kde je volné místo, které mapy hned po vydání letí a co frčí ve videích. Čísla z oficiálního API Epicu.",pts:["Verdikt podle žánru","Mapy, které fungují","Trendy TikTok a Shorts"]},{tag:"Výplaty",h:"Každý ví, kolik dostane.",p:"Pravidla dělení v procentech, pevnou částkou nebo za úkol, import výdělků, výpis pro každého. Konec tabulek ztracených na Discordu.",pts:["Procenta, pevně, za úkol","Import CSV","Výpis pro každého"]}],aiB:"Už používáte AI?",aiText:"Připojte Claude, Cursor, Codex nebo jinou AI kompatibilní s MCP: vezme úkol, napíše Verse, zkompiluje a úkol uzavře s poznámkou. Každá akce je zaznamenaná a vratná. Kompatibilní: Claude Code, Claude Desktop, Cursor, Codex, Windsurf, VS Code (GitHub Copilot), Gemini CLI."},stats:[["1 h","na úkol, abyste se každý den posunuli"],["0","povinných externích AI služeb"],["7 dní","statistik na mapu z API Epicu"],["100 %","akcí v UEFN lze vrátit"]],pricing:{eyebrow:"Ceník",h2:"Vyberte si tarif.",p:"POP je v uzavřené betě: přístup přes pořadník. Po spuštění začíná každý účet 7denní zkušební verzí Pro zdarma, bez karty.",perMonth:"/ měsíc",compare:"Porovnat tarify",unlimited:"Neomezeně",soon:"Brzy",plans:[{name:"Starter",tag:"Pro tvorbu",desc:"Celý pracovní prostor pro tvorbu map, sám nebo v týmu.",cta:"Zapsat se"},{name:"Pro",tag:"Nejúplnější",desc:"Vše ze Starteru a navíc analýza: nápady na mapy, trh, sledování Discover.",cta:"Zapsat se"}],rows:["Organizace","Hodinové úkoly, Kanban, závislosti","Vestavěný asistent (shrnutí dne, zpoždění)","Stránky, tabule, plánování a milníky","Mapy","Členové","UEFN","UEFN Link: synchronizované projekty","Organizér aktérů a hromadné úpravy","Připojené AI (Claude, Cursor, Codex…)","POP Forge: asistované stavění v UEFN","Růst","Nápady na mapy, analýza trhu, sledování Discover","Video trendy TikTok a YouTube Shorts","Výměna playtestů a den vydání","Dělení výdělků a výpisy","Discord, GitHub, Lore"],perDay:["Méně než 0,50 € denně","Méně než 1 € denně"],hints:["","Mapa rozdělená na hodinové úkoly, včetně toho, co co blokuje","Každé ráno: co má zpoždění a čím začít","Dokumentace mapy, nápady naživo a kalendář","Tolik map, kolik chcete","Pozvěte celý tým bez příplatku","","Vaše AI vidí skutečný projekt UEFN: aktéry a Verse","","Připojte svou AI přes MCP; každou akci lze vrátit","Stavění v UEFN podle jednoduchého zadání","","Žánry, které lákají hráče, a kde je ještě místo","Co právě roste na TikToku a YouTube Shorts","Najděte testery a připravte den vydání","Kdo dostane kolik, s výpisem pro každého","Oznámení a odkazy na vaše nástroje"]},faq:{eyebrow:"Otázky",h2:"Na co se nás ptáte.",items:[["Potřebuji PC s Windows?","Pro propojení s UEFN ano: UEFN běží jen na Windows a UEFN Link se spouští na tomto PC. Zbytek POP funguje v jakémkoli prohlížeči, i na Macu."],["Publikuje POP moji mapu?","Ne. POP vše připraví (kontrola před publikací, playtesty, plán dne vydání), ale publikace vždy probíhá na portálu tvůrců Epicu."],["Funguje POP, i když tvořím sám?","Ano. POP slouží sólo tvůrcům i týmům už od plánu Starter: členy můžete pozvat později, aniž byste cokoli měnili."],["Jaké AI můžu připojit?","Ty, které podporují servery MCP: Claude Code, Claude Desktop, Cursor, Codex, Windsurf, VS Code (GitHub Copilot), Gemini CLI. Claude Desktop vyžaduje, aby byl POP online přes HTTPS. Předplatné vaší AI není součástí POP. Chatovací AI v prohlížeči (ChatGPT, Gemini, Copilot na webu) zatím podporované nejsou. Po připojení v „Připojené AI“ vaše AI čte a upravuje úkoly a aktéry v UEFN, píše Verse a každá akce je zaznamenaná a vratná."],["Odkud jsou čísla v analýze?","Z oficiálního Fortnite API od Epicu: hráči, špička současných hráčů, herní čas a retence každé veřejné mapy za 7 dní."],["Jak získám přístup?","POP je v uzavřené betě. Zapište se na čekací listinu: žádosti procházíme jednu po druhé a pak vám pošleme uživatelské jméno a dočasné heslo, které při prvním přihlášení změníte."],["Kolik to stojí?","Ceny jsou uvedeny výše. Platí od otevření POP; členové bety budou upozorněni před jakoukoli platbou."]]},final:{h2a:"Vaše další mapa",h2b:"začíná tady.",p:"Zapište se na čekací listinu: přístup pošleme, jakmile se uvolní místo."},foot:{legalTitle:"Právní informace",made:"Vytvořeno tvůrci Fortnite pro tvůrce Fortnite.",legal:"Fortnite a UEFN jsou ochranné známky společnosti Epic Games. POP není s Epic Games spojen ani jí schválen.",product:"Produkt",help:"Nápověda",account:"Účet"},mock:{overview:"Přehled",nav:["Přehled","Stránky","Tabule","Úkoly","Organizér","Trh"],hello:"Ahoj Léo, navrhuji začít úkolem #42.",late:"2 úkoly ve zpoždění (nejstarší měl termín 12. 11.).",mile:"Milník „Beta“ za 5 dní: zbývá 9 úkolů, očekávané zpoždění 1 den.",take:"Vzít",start:"Začít",unlocks:"odemkne 3 další úkoly",today:"termín dnes",waits:"čeká na #42",todo:"K udělání",doing:"Rozpracováno",done:"Hotovo",tasks:["Systém skóre","Dekorace zóny 2","Závěrečná obrazovka","Interní playtest","Spawn hráčů","Bouře"],sent:"odesláno do UEFN",err:"Řádek 12: int a float nelze sečíst.",fix:"Opravit: Points += 1",red:"Červený tým",selected:"Vybráno: 2",rename:"Přejmenovat",move:"Přesunout",dup:"Duplikovat",s1:"Týmový režim 4v4",s2a:"Finální boss",s2b:"uprostřed",s3:"Ekonomika: 1 mince / eliminace",verdicts:["Dobrá příležitost","Populární, ale přeplněné","Nasycené","Nika"],typical:"hráčů / typická mapa",earnings:"Výdělky za říjen",roles:["Kód · 40 %","Mapa · 35 %","Hudba · pevně","Zbytek"],noTransfer:"POP počítá, nikdy nepřevádí peníze."},wl:{eyebrow:"Uzavřená beta",title:"Zapsat se na čekací listinu",intro:"POP otevíráme postupně, abychom se mohli věnovat každému tvůrci. Řekněte nám, kdo jste, a přístup vám pošleme co nejdřív.",pageIntro:"Během bety zakládá účty POP náš tým. Řekněte nám, kdo jste: po schválení dostanete uživatelské jméno a dočasné heslo.",invalid:"Tento přístupový odkaz je neplatný, už použitý nebo vypršel. Požádejte znovu, nebo napište týmu POP.",name:"Jméno nebo přezdívka",email:"E-mail",studio:"Studio",optional:"(nepovinné)",studioPh:"Název studia",team:"Velikost týmu",teams:["Sám","2–3","4–10","Víc než 10"],exp:"Zkušenosti",exps:["Nováček v UEFN","Pár vydaných map","Zkušený tvůrce","Profesionální studio"],links:"Vaše mapy nebo sítě",linksPh:"Kódy ostrovů, TikTok, YouTube…",msg:"Co chcete s POP dělat",msgPh:"Např. jsme 4 na tycoon mapě a ztrácíme se mezi Discordem a Google Docs.",send:"Požádat o přístup",sending:"Odesílání…",nospam:"Žádný spam: píšeme jen kvůli přístupu.",privacy:"Zásady ochrany soukromí",okTitle:"Zapsáno, díky!",okText:"Jakmile bude váš přístup připraven, obdržíte e-mail na zadanou adresu s odkazem pro aktivaci účtu. Zkontrolujte i složku se spamem.",alreadyTitle:"Už jste na seznamu.",approvedTitle:"Váš přístup je už schválený.",approvedText:"Váš účet je připraven: obdrželi jste e-mail s odkazem pro jeho aktivaci a volbu hesla. Zkontrolujte i složku se spamem.",close:"Zavřít"}};export{e as default};
